const input = $json;
const body = input.body || input;

const EXPECTED_TOKEN =
  'YOUR_PLN_FINALIZE_TRIGGER_TOKEN';

if (String(body.token || '') !== EXPECTED_TOKEN) {
  throw new Error('UNAUTHORIZED_FINALIZATION');
}

const fileId = String(body.file_id || '').trim();

if (!/^[A-Za-z0-9_-]{15,}$/.test(fileId)) {
  throw new Error('INVALID_REPORT_FILE_ID');
}

return {
  json: {
    authorized: true,
    file_id: fileId,
    action: 'finalize_pdf'
  }
};

const r = $input.item.json || {};
let p = r.body ?? r;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { throw new Error('APPS_SCRIPT_NON_JSON_RESPONSE: ' + p.slice(0, 400)); } }
if (p.ok !== true || p.status !== 'PREPARED') throw new Error('PREPARE_FAILED: ' + JSON.stringify(p).slice(0,1000));
const tn = String(p.tn_pdf_file_id || '').trim();
const comparison = String(p.comparison_pdf_file_id || '').trim();
const invoice = String(p.original_pdf_file_id || p.source_file_id || '').trim();
const folder = String(p.output_folder_id || '').trim();
if (!tn || !comparison || !invoice || !p.file_id || !folder) throw new Error('PDF_INPUTS_OR_FOLDER_MISSING: ' + JSON.stringify(p).slice(0,1000));
const filename = String(p.final_pdf_name || 'PLN_REPORT.pdf').replace(/\.pdf$/i, '').replace(/[\\/:*?"<>|]/g, '_') + '.pdf';
return {json:{ok:true,status:p.status,file_id:p.file_id,customer_id:p.customer_id,tn_pdf_file_id:tn,comparison_pdf_file_id:comparison,original_pdf_file_id:invoice,final_pdf_name:filename,output_folder_id:folder}};

// Exact order: TN -> Comparison -> Original PLN Invoice.
const report = $('Check Prepared1').first().json;
const tn = String($('Encode Temporary PDF1').first().json.tn_pdf_base64 || '');
const comparison = String($('Encode Comparison PDF').first().json.comparison_pdf_base64 || '');
const invoiceBytes = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!tn || !comparison || invoiceBytes.subarray(0, 5).toString() !== '%PDF-') throw new Error('MERGE_PDF_INPUTS_MISSING');
const invoice = invoiceBytes.toString('base64');
// CloudConvert recommends not using import/base64 for files >10 MB.
for (const [label, base64] of [['TN', tn], ['COMPARISON', comparison], ['INVOICE', invoice]]) {
  if (base64.length * 3 / 4 > 10 * 1024 * 1024) throw new Error(label + '_PDF_TOO_LARGE_FOR_CLOUDCONVERT_BASE64 (max 10 MB)');
}
if (!report.output_folder_id) throw new Error('OUTPUT_FOLDER_ID_MISSING_FROM_APPS_SCRIPT');
return [{
  json: {
    cloudconvert_payload: {
      tasks: {
        'import-tn': { operation: 'import/base64', file: tn, filename: 'TN.pdf' },
        'import-comparison': { operation: 'import/base64', file: comparison, filename: 'PERBANDINGAN.pdf' },
        'import-invoice': { operation: 'import/base64', file: invoice, filename: 'INVOICE_PLN.pdf' },
        'merge-pln': {
          operation: 'merge',
          input: ['import-tn', 'import-comparison', 'import-invoice'],
          output_format: 'pdf',
          filename: report.final_pdf_name
        },
        'export-pln': { operation: 'export/url', input: 'merge-pln' }
      }
    }
  }
}];

const job = $input.first().json.data;
if (!job || job.status !== 'finished') {
  throw new Error('CLOUDCONVERT_NOT_FINISHED: ' + JSON.stringify({
    status: job?.status,
    errors: job?.tasks?.filter(t => t.status === 'error').map(t => t.message)
  }));
}
const exp = (job.tasks || []).find(t => t.name === 'export-pln');
const files = exp?.result?.files || [];
if (exp?.status !== 'finished' || files.length !== 1 || !files[0].url) {
  throw new Error('CLOUDCONVERT_EXPORT_MISSING');
}
const src = $('Check Prepared1').first().json;
return [{
  json: {
    file_id: src.file_id,
    output_folder_id: src.output_folder_id,
    final_pdf_name: src.final_pdf_name,
    download_url: files[0].url,
    cloudconvert_job_id: job.id
  }
}];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buf.subarray(0, 5).toString() !== '%PDF-') throw new Error('CLOUDCONVERT_DOWNLOAD_NOT_PDF');
const src = $('Check Prepared1').first().json;
const data = $input.item.binary?.data;
if (!data) throw new Error('MERGED_PDF_BINARY_MISSING');
return {
  json: {
    file_id: src.file_id,
    final_pdf_name: src.final_pdf_name,
    output_folder_id: src.output_folder_id,
    pdf_size_bytes: buf.length
  },
  binary: { data }
};

